MODIFIED=("prisma/schema.prisma")
CREATED=("prisma/migrations/20261209000000_image_consent_online/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261209000000_image_consent_online" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "model ImageConsentRequest" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
